# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: `ds settings` commands: store the secrets in ds.settings (keyring) and show them.
#
# Example CLI Commands:
#   0. Store / replace secrets:        uv run ds settings sync
#   1. Same, with how to get each one: uv run ds settings sync --guide
#   2. Show what is stored (masked):   uv run ds settings show
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import Annotated

import typer
from ds.settings import get_settings, set_settings
from pydantic import BaseModel
from rich import print as rprint

__all__ = ["settings_app"]

settings_app = typer.Typer(help="SubCommands for syncing up settings")


class _Secret(BaseModel):
    """What `sync` shows for one secret: where it comes from and how to get it"""

    field: str  # the Settings field / set_settings keyword
    prompt: str
    used_by: str
    url: str
    steps: list[str]


_SECRETS = [
    _Secret(
        field="pydantic_gateway_api_key",
        prompt="Pydantic AI Gateway key (eg pylf_v1_us_xxxx)",
        used_by="all ds.ai model calls",
        url="https://logfire-us.pydantic.dev",
        steps=[
            "Open the Logfire project, then Gateway > Connect.",
            "Create a key and copy it (starts with `pylf_`).",
        ],
    ),
    _Secret(
        field="startgg_api_token",
        prompt="start.gg API token",
        used_by="ds.data.raw.startgg (player sets, tournaments)",
        url="https://start.gg/admin/profile/developer",
        steps=[
            "Log in to start.gg and open the link (Profile > Developer Settings).",
            "Click 'Create new token' and give it a description, eg delulu-smash.",
            "Save and copy it right away: it is shown only once.",
            "Limits: 80 requests per 60 s, 1000 objects per request. The token expires after one year.",
        ],
    ),
]


def _ask(secret: _Secret, stored: object, guide: bool) -> str | None:
    """Prompt for one secret; Enter keeps the stored value (returns None)"""
    rprint(f"\n[bold]{secret.prompt}[/bold] [dim]- used by {secret.used_by}[/dim]")
    rprint(f"  Get it at: {secret.url}")
    if guide:
        for number, step in enumerate(secret.steps, start=1):
            rprint(f"  {number}. {step}")
    keep = f"Enter keeps {stored}" if stored is not None else "Enter skips"
    return typer.prompt(f"  Paste it ({keep})", hide_input=True, default="", show_default=False) or None


@settings_app.command("sync")
def sync(
    guide: Annotated[bool, typer.Option("--guide", help="Show the steps for getting each secret")] = False,
) -> None:
    """Store secrets (Pydantic AI Gateway key, start.gg API token) in the keyring

    Each prompt shows where to get the value; `--guide` adds the steps. Pressing Enter keeps
    what is already stored.
    """
    current = get_settings()
    if not guide:
        rprint("[dim]Not sure how to get one of these? Run `ds settings sync --guide`.[/dim]")
    answers = {secret.field: _ask(secret, getattr(current, secret.field), guide) for secret in _SECRETS}
    set_settings(**answers)
    rprint(f"\nCurrent Settings: {get_settings()}")


@settings_app.command("show")
def show() -> None:
    """Display current settings"""
    print(get_settings())
